// Package stations keeps the railway station directory: it syncs the embedded CSV into the
// stations table on start and serves lookups and search from memory (about 1 200 rows).
package stations

import (
	"bytes"
	"cmp"
	"context"
	"encoding/csv"
	"fmt"
	"slices"
	"strconv"
	"strings"

	"github.com/Andas-LV/cargoflow/services/shipment/internal/repository/db"
)

// Station is a directory entry (generated by sqlc).
type Station = db.Station

const (
	KindStation = "station"
	KindHalt    = "halt"
)

const (
	defaultLimit = 20
	maxLimit     = 50
)

// ParseCSV reads stations_kz.csv (header: id,esr,kind,name,name_ru,name_kk,name_en,lat,lon).
func ParseCSV(data []byte) ([]Station, error) {
	r := csv.NewReader(bytes.NewReader(data))
	rows, err := r.ReadAll()
	if err != nil {
		return nil, fmt.Errorf("parse stations csv: %w", err)
	}
	if len(rows) < 2 {
		return nil, fmt.Errorf("stations csv is empty")
	}
	stations := make([]Station, 0, len(rows)-1)
	for i, row := range rows[1:] {
		if len(row) != 9 {
			return nil, fmt.Errorf("stations csv line %d: want 9 columns, got %d", i+2, len(row))
		}
		lat, err1 := strconv.ParseFloat(row[7], 64)
		lon, err2 := strconv.ParseFloat(row[8], 64)
		if err1 != nil || err2 != nil {
			return nil, fmt.Errorf("stations csv line %d: bad coordinates", i+2)
		}
		stations = append(stations, Station{
			ID: row[0], Esr: row[1], Kind: row[2], Name: row[3],
			NameRu: row[4], NameKk: row[5], NameEn: row[6], Lat: lat, Lon: lon,
		})
	}
	return stations, nil
}

// Sync upserts stations into the database in one statement.
func Sync(ctx context.Context, q *db.Queries, stations []Station) error {
	p := db.UpsertStationsParams{}
	for _, s := range stations {
		p.Ids = append(p.Ids, s.ID)
		p.Esrs = append(p.Esrs, s.Esr)
		p.Kinds = append(p.Kinds, s.Kind)
		p.Names = append(p.Names, s.Name)
		p.NamesRu = append(p.NamesRu, s.NameRu)
		p.NamesKk = append(p.NamesKk, s.NameKk)
		p.NamesEn = append(p.NamesEn, s.NameEn)
		p.Lats = append(p.Lats, s.Lat)
		p.Lons = append(p.Lons, s.Lon)
	}
	if err := q.UpsertStations(ctx, p); err != nil {
		return fmt.Errorf("upsert stations: %w", err)
	}
	return nil
}

// Directory is an in-memory, read-only copy of the stations table.
type Directory struct {
	byID map[string]Station
	all  []entry
}

type entry struct {
	station Station
	keys    []string // normalized names used for search
}

// Load reads all stations from the database.
func Load(ctx context.Context, q *db.Queries) (*Directory, error) {
	rows, err := q.ListStations(ctx)
	if err != nil {
		return nil, fmt.Errorf("load stations: %w", err)
	}
	return New(rows), nil
}

// New builds a directory from stations (used by Load and tests).
func New(stations []Station) *Directory {
	d := &Directory{byID: make(map[string]Station, len(stations)), all: make([]entry, 0, len(stations))}
	for _, s := range stations {
		d.byID[s.ID] = s
		var keys []string
		for _, name := range []string{s.NameRu, s.Name, s.NameKk, s.NameEn} {
			if k := normalize(name); k != "" && !slices.Contains(keys, k) {
				keys = append(keys, k)
			}
		}
		d.all = append(d.all, entry{station: s, keys: keys})
	}
	return d
}

func (d *Directory) Len() int { return len(d.byID) }

func (d *Directory) Get(id string) (Station, bool) {
	s, ok := d.byID[id]
	return s, ok
}

// Search matches query against all names and the ESR code. Results are ranked:
// exact name, then name prefix, then word prefix, then substring; stations before halts.
func (d *Directory) Search(query string, limit int) []Station {
	q := normalize(query)
	if q == "" {
		return nil
	}
	if limit <= 0 {
		limit = defaultLimit
	}
	limit = min(limit, maxLimit)

	type hit struct {
		station Station
		rank    int
	}
	var hits []hit
	for _, e := range d.all {
		best := -1
		if e.station.Esr != "" && e.station.Esr == q {
			best = 0
		}
		for _, k := range e.keys {
			if r := matchRank(k, q); r >= 0 && (best < 0 || r < best) {
				best = r
			}
		}
		if best >= 0 {
			hits = append(hits, hit{station: e.station, rank: best})
		}
	}

	slices.SortFunc(hits, func(a, b hit) int {
		return cmp.Or(
			cmp.Compare(a.rank, b.rank),
			cmp.Compare(kindOrder(a.station.Kind), kindOrder(b.station.Kind)),
			strings.Compare(a.station.NameRu, b.station.NameRu),
		)
	})
	result := make([]Station, 0, min(limit, len(hits)))
	for _, h := range hits[:min(limit, len(hits))] {
		result = append(result, h.station)
	}
	return result
}

// matchRank: 0 exact, 1 prefix, 2 word prefix, 3 substring, -1 no match.
func matchRank(name, q string) int {
	switch {
	case name == q:
		return 0
	case strings.HasPrefix(name, q):
		return 1
	case strings.Contains(name, " "+q):
		return 2
	case strings.Contains(name, q):
		return 3
	default:
		return -1
	}
}

func kindOrder(kind string) int {
	if kind == KindStation {
		return 0
	}
	return 1
}

// fold makes Kazakh letters, "ё" and hyphens searchable with a Russian keyboard:
// "жезказган" finds "Жезқазған", "алматы 1" finds "Алматы-1".
var fold = strings.NewReplacer(
	"ә", "а", "ғ", "г", "қ", "к", "ң", "н", "ө", "о", "ұ", "у", "ү", "у", "һ", "х", "і", "и",
	"ё", "е", "-", " ",
)

func normalize(s string) string {
	return strings.Join(strings.Fields(fold.Replace(strings.ToLower(s))), " ")
}
